/**
 * Content Catalog (§7, §8, §9, §10)
 * ----------------------------------
 * Pure data. Adding a category or word requires NO change to game engine, UI,
 * role engine, voting, or score engine.
 *
 * Quality criteria (§9):
 * - Words must be understandable & playable for 3-12 players
 * - Words should invite discussion / different interpretations
 * - Multiple words may share a hint (semantic grouping, §10)
 *
 * v2.4.0 Catalog — 64 categories, 6400+ unique words.
 */

import type { Category } from '../models'

/**
 * Special category ID for "random" mode.
 * When this ID is used, the game picks a random real category at session creation.
 * The category is NOT shown to the players — they just see "Zufall".
 */
export const RANDOM_CATEGORY_ID = '__random__'

/**
 * Total word count across ALL built-in categories.
 * Used by the UI to show the word count when "Zufall" is selected.
 */
export function getTotalWordCount(): number {
  return CATALOG.reduce((sum, cat) => sum + cat.words.length, 0)
}

/**
 * Pick a random built-in category (used when RANDOM_CATEGORY_ID is selected).
 */
function pickRandomCategory(): Category {
  if (CATALOG.length === 0) throw new Error('Catalog is empty.')
  return CATALOG[Math.floor(Math.random() * CATALOG.length)]
}

