/**
 * Get a category by ID. Throws if not found — the catalog is the source of truth.
 */
export function getCategoryById(id: string): Category {
  // Handle random category — pick a random one (sync, built-in only)
  if (id === RANDOM_CATEGORY_ID) return pickRandomCategory()
  const cat = CATALOG.find(c => c.id === id)
  if (!cat) throw new Error(`Unknown category: ${id}`)
  return cat
}


/**
 * Async version — checks both built-in CATALOG and custom categories from IndexedDB.
 * Used when the game session is created to resolve the selected category.
 */
export async function getCategoryByIdAsync(id: string): Promise<Category> {
  // Handle random category — pick a random built-in category
  if (id === RANDOM_CATEGORY_ID) return pickRandomCategory()
  // Check built-in first
  const builtin = CATALOG.find(c => c.id === id)
  if (builtin) return builtin
  // Check custom categories from IndexedDB
  try {
    const { listCustomCategories } = await import('../../repositories/categoryRepository')
    const custom = await listCustomCategories()
    const found = custom.find(c => c.id === id)
    if (found) {
      return { id: found.id, displayName: found.displayName, icon: found.icon, words: found.words }
    }
  } catch {
    // ignore
  }
  throw new Error(`Unknown category: ${id}`)
}

/**
 * Get all categories except the one with the given ID.
 * Used by Jester word selection (§12: must come from a different category).
 */
export function getOtherCategories(currentId: string): Category[] {
  return CATALOG.filter(c => c.id !== currentId)
}
